from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from ..critic import CriticFinding


@dataclass(frozen=True)
class ArchitectProposal:
    """Proposal formulated by the Architect Agent decomposing a software engineering task."""

    task_title: str
    target_files: tuple[str, ...]
    architecture_notes: str
    proposed_steps: tuple[dict[str, Any], ...]


@dataclass(frozen=True)
class CodeProposal:
    """Proposed code changes or unified diff generated by the Coder Agent."""

    step_id: str
    description: str
    patch_or_content: str
    target_file: str
    is_unified_diff: bool = True


@dataclass(frozen=True)
class CriticVerdict:
    """Consensus review emitted by the Security & Architecture Critic."""

    approved: bool
    risk_score: float
    findings: tuple[CriticFinding, ...]
    critique_notes: str


@dataclass(frozen=True)
class CouncilDeliberationResult:
    """Final consensus reached by the Council of Specialized Agents."""

    task_title: str
    consensus_reached: bool
    iterations_used: int
    architect_proposal: ArchitectProposal
    code_proposals: tuple[CodeProposal, ...]
    critic_verdict: CriticVerdict
    summary: str
